def html_attrs(s): return escape(str(s),quote=True)

def desktop_content(title,mode,fields):
    opts = '<div class="callout"><span>Conteúdo protegido por permissões do escritório</span><span class="btn">+ Ação principal</span></div>'
    if mode=='login': return '<div class="split"><div class="split-box"><h2>Bem-vindo ao SysADV</h2><p>Gestão jurídica mais inteligente.</p><div class="chart-card">Processos, documentos, cálculos e integrações em um só lugar.</div></div><div class="split-box"><h2>Acesso ao sistema</h2>'+''.join(f'<div class="field">{escape(x)}<span>Preencha para continuar</span></div>' for x in fields[:2])+'<p class="btn">Acessar sistema</p></div></div>'
    if mode=='dashboard': return '<div class="kpis">'+''.join(f'<div class="kpi"><small>{escape(x)}</small><strong>{v}</strong></div>' for x,v in zip(fields,['128','24','36','09']))+'</div><div class="split"><div class="chart-card"><h3>Processos por fase</h3><div class="bar"></div><div class="bar"></div><div class="bar"></div></div><div class="chart-card"><h3>Atividades recentes</h3><div class="line">Publicação capturada</div><div class="line">Tarefa atualizada</div></div></div>'
    if mode=='table':
      cols=''.join(f'<span>{escape(x)}</span>' for x in fields[:6])
      rows=''.join('<div class="trow">'+''.join(f'<span class="{("row-link" if j==0 else "")}">{escape(v)}</span>' for j,v in enumerate([f'Registro {i+1}','Cliente de referência','Pessoa jurídica','Em andamento','07/11/2026','Consultar']))+'</div>' for i in range(4))
      return '<div class="filters"><div class="filter">Buscar por termo...</div><div class="filter">Situação ▾</div><div class="filter">Período ▾</div></div><div class="table"><div class="trow head">'+cols+'</div>'+rows+'</div>'
    if mode=='form': return '<div class="form">'+''.join(f'<div class="field">{escape(f)}<span>Informe {escape(f.lower())}</span></div>' for f in fields[:6])+'<div class="form-footer"><span class="btn">Salvar alterações</span></div></div>'
    if mode=='detail': return '<div class="info-grid">'+''.join(f'<div class="info"><small>{escape(x)}</small><strong>Informação do processo</strong></div>' for x in fields[:6])+'</div><div class="timeline"><b>Histórico e evidências</b>'+''.join(f'<div class="event">{escape(x)} — atualizado com rastreabilidade</div>' for x in fields[:4])+'</div>'
    if mode=='split': return '<div class="split"><div class="split-box"><b>Pesquisar e selecionar</b>'+''.join(f'<div class="line">{escape(x)}</div>' for x in fields[:4])+'</div><div class="split-box"><b>Dados e edição</b><div class="form">'+''.join(f'<div class="field">{escape(x)}<span>Informação cadastrada</span></div>' for x in fields[:4])+'</div></div></div>'
    if mode=='kanban': return '<div class="kanban">'+''.join(f'<div class="kan-col">{escape(f)}'+''.join(f'<div class="kan-card">Tarefa jurídica #{i+1}<br/><br/><span class="chip">Prioridade normal</span></div>' for i in range(2))+'</div>' for f in fields[:4])+'</div>'
    if mode=='calendar': return '<div class="calendar">'+''.join(f'<div class="cal-day heading">{escape(x)}</div>' for x in fields[:7])+''.join(f'<div class="cal-day {"selected" if i==12 else ""}">{(i%30)+1}<br/><span class="chip">{(i%3)+1} evento(s)</span></div>' for i in range(28))+'</div>'
    if mode=='integration': return '<div class="integration-cards">'+''.join(f'<div class="integration-card"><b>{escape(f)}</b><small>Conexão condicionada</small><span class="chip">Verificar status</span></div>' for f in fields[:6])+'</div><div class="chart-card"><h3>Execuções e atividades recentes</h3><div class="line">Monitoramento de conexões</div><div class="line">Revisar permissões e evidências</div></div>'
    return opts

def mobile_content(title,mode,fields):
    heading=f'<div class="mobile-header"><span>☰ &nbsp; SysADV</span><span>DS</span></div><div class="mobile-main"><h3>{escape(title)}</h3>'
    if mode=='login': return heading+'<div class="mobile-card"><b>Acesso ao sistema</b></div><div class="mobile-input">E-mail</div><div class="mobile-input">Senha</div><div class="mobile-action">Acessar sistema</div></div>'
    if mode=='form': return heading+''.join(f'<div class="mobile-input">{escape(f)}</div>' for f in fields[:6])+'<div class="mobile-action">Salvar alterações</div></div>'
    if mode=='calendar': return heading+'<div class="mobile-card"><small>Hoje, 7 de novembro</small><b>Compromissos do dia</b><div class="divider"></div><b>09h · Audiência</b><small>Processo de referência</small></div><div class="mobile-card"><b>14h · Reunião</b><small>Compromisso do escritório</small></div></div>'
    if mode=='kanban': return heading+'<div class="mobile-card"><small>Em andamento (2)</small><b>Tarefa jurídica prioritária</b><span class="chip">Em andamento</span></div><div class="mobile-card"><small>Em revisão (1)</small><b>Conferência de documento</b></div></div>'
    if mode=='dashboard': return heading+''.join(f'<div class="mobile-card"><small>{escape(f)}</small><b>{v}</b></div>' for f,v in zip(fields[:4],['128','24','36','09']))+'</div>'
    if mode=='integration': return heading+''.join(f'<div class="mobile-card"><small>Fonte oficial</small><b>{escape(f)}</b><span class="chip">Credenciamento</span></div>' for f in fields[:3])+'</div>'
    return heading+'<div class="mobile-input">Pesquisar...</div>'+''.join(f'<div class="mobile-card"><small>{escape(fields[0])}</small><b>{"Registro de referência " + str(i+1)}</b><div class="divider"></div><small>{escape(fields[min(1,len(fields)-1)])}: informação</small><div class="mobile-action">Abrir detalhes</div></div>' for i in range(3))+'</div>'

def create_page(index,page):
    title,path,area,mode,fields,benefits=page
    nav_html=''.join('<div class="nav-label">'+escape(group)+'</div>'+''.join(f'<div class="nav-item {"selected" if item.lower() == title.lower() or (title.startswith("Novo processo") and item=="Processos") else ""}">{escape(item)}</div>' for item in items) for group,items in nav)
    contents=desktop_content(title,mode,fields)
    notes='<div class="notes"><h4>Padrão para esta tela</h4>'+''.join(f'<p>• {escape(x)}</p>' for x in benefits)+'</div>'
    return f'''<section class="page" data-document-role="page" data-label="{html_attrs(title)}">
      <header class="page-header"><div><span class="series">SysADV | Protótipo de UI · v0.9.2 UI r4</span><h1>{escape(title)}</h1></div><span class="page-num">{index:02d} / {len(pages):02d} &nbsp; • &nbsp; {escape(path)}</span></header>
      <div class="page-body"><div class="column"><div class="preview-label">Desktop · 1440 px (esquema)</div><div class="screen"><aside class="screen-side"><div class="logo">Sys<em>ADV</em></div>{nav_html}</aside><div class="screen-main"><header class="screen-top"><span>Área de trabalho / <b>{escape(title)}</b></span><span class="search">Buscar tela ou funcionalidade...</span><span>DS &nbsp; ◉</span></header><div class="screen-content"><span class="eyebrow">{escape(area)}</span><h2>{escape(title)}</h2><p>Interface organizada para consulta, operação e rastreabilidade.</p>{contents}</div></div></div><div class="notes"><h4>Responsividade e acessibilidade</h4><p>Componentes fluidos, toque confortável, foco visível, ações preservadas, sem rolagem horizontal da página.</p></div></div><div class="column"><div class="preview-label">Mobile · 390 px (esquema)</div><div class="mobile">{mobile_content(title,mode,fields)}</div>{notes}</div></div><div class="footer">REFERÊNCIA CONCEITUAL · DESIGN NÃO HOMOLOGADO · NÃO CONTÉM DADOS REAIS</div>
    </section>'''

html='<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SysADV — 19 telas · Referência de UI responsiva</title><style>'+CSS+'</style></head><body>'+''.join(create_page(i+1,p) for i,p in enumerate(pages))+'</body></html>'
output=Path('/mnt/data/sysadv_ui_modern/docs/ui-modernizacao')
output.mkdir(parents=True,exist_ok=True)
(output/'SysADV_Canva_Referencia_19_Telas_UI_r4.html').write_text(html,encoding='utf-8')
print('wrote',len(pages),'pages',len(html),'chars')
